/bin/bash -lc "python - <<'PY'
import statistics
arr=[]
for line in open('coverage_100kb.tsv'):
    c,s,e,v=line.rstrip().split('\\t')
    if c=='chr22': arr.append((int(s),int(e),float(v)))
# print all nonzero before 16M
print('pre16 nonzero')
for s,e,v in arr:
    if e<=16000000 and v>0:
        print(s,e,v)
# median q arm >16M excluding zeros
q=[v for s,e,v in arr if s>=16000000 and v>0]
print('q median',statistics.median(q),'mean',sum(q)/len(q),'n',len(q))
# bins > 1.2*qmed and >1.1 etc
for mult in [1.1,1.2,1.3]:
    th=statistics.median(q)*mult
    seg=[]; i=0; mask=[(s>=16000000 and v>th) for s,e,v in arr]
    while i<len(mask):
        if mask[i]:
            j=i+1
            while j<len(mask) and mask[j]: j+=1
            if j-i>=1: seg.append((arr[i][0],arr[j-1][1],j-i,sum(arr[k][2] for k in range(i,j))/(j-i)))
            i=j
        else: i+=1
    print('mult',mult,'th',th,'segments',seg[:20])
# top q bins sorted
print('top q')
for s,e,v in sorted([x for x in arr if x[0]>=16000000], key=lambda x:x[2], reverse=True)[:30]: print(s,e,v)
PY"

